    private JwtDecoder jwtDecoder;
    
    @Mock
    private HttpServletRequest request;
    
    @Mock
    private HttpServletResponse response;
    
    @Mock
    private FilterChain filterChain;
    
    private DeskJwtValidationFilter filter;
    private Set<String> exclusions;
    private AntPathMatcher matcher;
    private StringWriter responseWriter;

    @BeforeEach
    void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        exclusions = new HashSet<>(Arrays.asList("/public/**", "/actuator/**"));
        matcher = new AntPathMatcher();
        filter = new DeskJwtValidationFilter(exclusions, matcher, jwtDecoder);
        
        responseWriter = new StringWriter();
        when(response.getWriter()).thenReturn(new PrintWriter(responseWriter));
    }

    @Test
    void testValidJwtWithRoles() throws Exception {
        // Valid JWT with roles claim
        String token = "valid.jwt.token";
        when(request.getHeader("Authorization")).thenReturn("Bearer " + token);
        when(request.getServletPath()).thenReturn("/api/protected");
        when(request.getMethod()).thenReturn("GET");
        
        Map<String, Object> role1 = new HashMap<>();
        role1.put("idRuolo", "ADMIN");
        
        Map<String, Object> role2 = new HashMap<>();
